import socket

def scan_ports(host: str, ports: list[int]) -> dict[int, bool]:
    result = {}
    for p in ports:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(0.5)
        try:
            s.connect((host, p))
            result[p] = True
        except (socket.timeout, socket.error):
            result[p] = False
        finally:
            s.close()
    return result
