def verify_access_log(log_path: str, allowed_ips: list[str]) -> list[str]:
    """Return IPs found in log_path that are not in allowed_ips."""
    unauthorized = set()
    allowed = set(allowed_ips)
    with open(log_path, "r") as f:
        for line in f:
            ip = line.split()[0]  # assume IP is first token
            if ip and ip not in allowed:
                unauthorized.add(ip)
    return list(unauthorized)
