import time, datetime, psutil

def monitor_connections(host: str, interval_s: int) -> list[dict]:
    end = time.time() + interval_s
    logs = []
    while time.time() < end:
        for c in psutil.net_connections(kind='inet'):
            if c.laddr.ip == host and c.raddr and c.status == 'ESTABLISHED':
                logs.append({
                    "timestamp": datetime.datetime.utcnow().isoformat(),
                    "source_ip": c.raddr.ip,
                    "source_port": c.raddr.port
                })
        time.sleep(1)
    return logs
```

