def _hash_value(val: str) -> str:
    return hashlib.sha256(val.encode()).hexdigest()

def anonymize_dataset(records: list[dict], fields: list[str]) -> list[dict]:
    """Return a copy of records with specified fields hashed."""
    result = deepcopy(records)
    for rec in result:
