import os
import stat

def find_writable_files(directory: str) -> list[str]:
    writable = []
    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            try:
                mode = os.stat(path).st_mode
                # check if world-writable or writable by group/owner when running as non-root
                if mode & (stat.S_IWOTH | stat.S_IWGRP | stat.S_IWUSR):
                    writable.append(path)
            except OSError:
                continue
    return writable
