from scapy.all import rdpcap, DNSQR
import math
import re
from collections import Counter

def _entropy(s: str) -> float:
    p = Counter(s)
    return -sum((c/len(s))*math.log2(c/len(s)) for c in p.values())

def _is_base64(s: str) -> bool:
    return bool(re.fullmatch(r'[A-Za-z0-9+/=]{8,}', s))

def analyze_dns_traffic(pcap_file: str) -> dict:
    pkts = rdpcap(pcap_file)
    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}
    seen = set()

    for pkt in pkts:
        if DNSQR in pkt:
            qname = pkt[DNSQR].qname.decode().strip('.')
            if qname in seen:
                continue
            seen.add(qname)

            labels = qname.split('.')
            # DGA: high entropy, long label, random chars
            if any(len(l) > 12 and _entropy(l) > 3.5 for l in labels):
                suspicious["dga"].append(qname)
                continue

            # Tunneling: many subdomains, often base64 chunks
            if len(labels) > 4 and any(_is_base64(l) for l in labels):
                suspicious["tunneling"].append(qname)
                continue

            # Exfiltration: queries with many numeric/hex chars, often in TXT or A
            if any(re.fullmatch(r'[0-9a-fA-F]{8,}', l) for l in labels):
                suspicious["exfiltration"].append(qname)

    return {k: list(dict.fromkeys(v)) for k, v in suspicious.items()}
```

